import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"Quick start: your first video in 10 minutes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),n={name:"guide/quick-start.md"};function o(r,e,h,d,l,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="quick-start-your-first-video-in-10-minutes" tabindex="-1">Quick start: your first video in 10 minutes <a class="header-anchor" href="#quick-start-your-first-video-in-10-minutes" aria-label="Permalink to &quot;Quick start: your first video in 10 minutes&quot;">​</a></h1><p>This walk-through makes a 30-second episode from an industry template, previews it without a recording, then adds your voice and renders. You need ReelForge <a href="./installation.html">installed</a> and <code>reelforge doctor</code> passing. Commands use <code>reelforge</code>; on Windows type <code>reelforge.cmd</code>, on macOS and Linux <code>./reelforge</code>.</p><h2 id="_1-create-an-episode-from-a-template-1-minute" tabindex="-1">1. Create an episode from a template (1 minute) <a class="header-anchor" href="#_1-create-an-episode-from-a-template-1-minute" aria-label="Permalink to &quot;1. Create an episode from a template (1 minute)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> healthcare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> patient-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en</span></span></code></pre></div><p>This writes <code>episodes/clinic-intro/episode.yaml</code> with a script, scenes and estimated (draft) cues, so the episode previews immediately. Use <code>--lang ar</code> for an Arabic voice-over. The <a href="./../reference/packs.html">pack catalog</a> lists every pack and template, and the dashboard offers the same choice under <strong>+ New episode</strong> → <strong>Start from template</strong>.</p><p>Prefer a blank start? <code>reelforge new ep10 --series &quot;SYSTEM DESIGN&quot;</code> creates a commented template, or click <strong>+ New episode</strong> in the dashboard (<code>start.bat</code> / <code>./start.sh</code>).</p><h2 id="_2-open-the-editor-and-make-it-yours-4-minutes" tabindex="-1">2. Open the editor and make it yours (4 minutes) <a class="header-anchor" href="#_2-open-the-editor-and-make-it-yours-4-minutes" aria-label="Permalink to &quot;2. Open the editor and make it yours (4 minutes)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><ul><li>In the <strong>Script</strong> tab on the left, edit the lines. Keep <strong>one spoken sentence per line</strong>, about 2.3 words per second. Line 1 is your hook.</li><li>Click an element on the canvas and change its text in the inspector, or double-click to edit in place. Words between <code>**</code> get the accent color: <code>**Duplicate** Charge</code>.</li><li>To make an element appear on a word, put the playhead on that word and click the <strong>target</strong> button next to <strong>Enter at</strong>. The editor writes a time such as <code>l3:&#39;desk&#39;</code>, which stays on the word after you re-record.</li><li><strong>Insert</strong> adds a component (or drag one onto the canvas). Drag clips on the timeline to retime them; they snap to your words.</li></ul><p>Everything is saved to <code>episode.yaml</code> as you go, with comments kept.</p><h2 id="_3-check-it-1-minute" tabindex="-1">3. Check it (1 minute) <a class="header-anchor" href="#_3-check-it-1-minute" aria-label="Permalink to &quot;3. Check it (1 minute)&quot;">​</a></h2><p>Switch to <strong>Review</strong> (<strong>Alt+3</strong>). Each issue, such as text that overflows or an element under the platform buttons, comes with a fix hint; click it to jump to the element. From the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l1+1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l3+1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # PNG frames in episodes/clinic-intro/out/snaps</span></span></code></pre></div><h2 id="_4-record-and-align-3-minutes" tabindex="-1">4. Record and align (3 minutes) <a class="header-anchor" href="#_4-record-and-align-3-minutes" aria-label="Permalink to &quot;4. Record and align (3 minutes)&quot;">​</a></h2><p>Record yourself reading the script with any app (phone, Audacity, OBS…), leaving a short pause between sentences. In the dashboard click <strong>Upload voice</strong> (WAV, MP3, M4A, OGG, OPUS or FLAC are converted to <code>voice.wav</code>), or save the file as <code>episodes/clinic-intro/voice.wav</code>. Then mark the cues:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><p>Open <strong>Cues</strong> mode (<strong>Alt+2</strong>), listen through once and fix any line by ear (press <strong>Space</strong> at the start of a line). <a href="./timing.html">Timing, cues and alignment</a> explains the details.</p><h2 id="_5-render-1-minute-to-start" tabindex="-1">5. Render (1 minute to start) <a class="header-anchor" href="#_5-render-1-minute-to-start" aria-label="Permalink to &quot;5. Render (1 minute to start)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><p>Or click <strong>Render</strong> (<strong>⌘/Ctrl+Enter</strong>) in the editor. When it finishes, upload <code>episodes/clinic-intro/out/clinic-intro.share.mp4</code> with the caption and hashtags from <code>out/publish.md</code>. No recording yet? <code>reelforge render clinic-intro --silent</code> renders a preview with the draft timing.</p><blockquote><p>Prefer working with an AI assistant? See <a href="./ai.html">AI integration</a>. An assistant can write the script, build the scenes and check the frames for you through the MCP server.</p></blockquote>`,21)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
